-- Only seeded rows (no creator) are rewritten; owner-added and admin-approved products keep their ingredients.
DELETE FROM food_product_ingredient
WHERE product_id IN (SELECT id FROM food_product WHERE created_by IS NULL AND status = 'PUBLIC');

